"""Freeze local design before DEV; freeze one finalist before fresh execution."""
import argparse,json,sys
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from src.common import CASE,sha,write_json,utc
from src.backends import IDS,ALIASES,effective
from src.protocol import verify_phase

def main():
 p=argparse.ArgumentParser();p.add_argument('--phase',choices=['a','b'],required=True);p.add_argument('--dev-summary',type=Path);a=p.parse_args();target=CASE/f'configs/phase_{a.phase}.json';assert not target.exists()
 audit=json.loads((CASE/'provenance/source_audit.json').read_text());support=[]
 for cid in IDS:
  probe=json.loads((CASE/f'provenance/probe-{cid}.json').read_text());support.append(dict(config_id=cid,**effective(cid),status=probe['status'],evidence=f'provenance/probe-{cid}.json',reason='Zero-scale/nonfinite after V smoothing on constant channels; excluded without patch' if cid=='V3' else 'Executed and semantic fixture verified',observed_kernel=probe.get('profile',{}).get('ops',[]),binary_sha256=audit['environment']['sage_binary_sha256'],source_sha256=audit['environment']['sage_core_sha256']))
 support.append(dict(config_id='A_MATCHED',status='ALIAS_OF_OTHER_CONFIG',alias_of='A_PUBLIC',reason='Case004 already calls explicit lower FP8 API with same options'))
 if a.phase=='a':
  write_json(CASE/'provenance/support_table.json',{'configs':support})
  s=dict(protocol_version=1,phase='A',frozen_at_utc=utc(),registration='Local protocol fixed before DEV real-trace comparison; not external preregistration',environment_fingerprint=audit['environment_fingerprint'],model_id='Qwen/Qwen3-0.6B',model_revision='c1899de289a04d12100db370d81485cdf75e47ca',geometry=dict(batch=1,hq=16,hkv=8,dim=128,layer_zero_based=13,causal=True,primary_length=4096,secondary_lengths=[512,2048]),candidate_priority=['V1','V2','V3','V4'],executable_configs=[x['config_id'] for x in support if x['status']=='EXECUTABLE_VERIFIED'],aliases=ALIASES,bf16_backend='default, inherited frozen Case004 choice at every Qwen length',screen=dict(median_error_max=.01,p95_error_max=.03,full_output_nonfinite_max=0,reference_rms_floor=1e-6,speedup_min=1.50,confirmation_speedup_ci_lower_strict=1.0,undefined='INCONCLUSIVE, no epsilon or dropped unit'),selection='Choose eligible NEW variant with highest DEV paired median speedup; tie lower p95 error, then config_id; no runner-up on fresh',reference=dict(dtype='BF16 inputs to FP32 score/softmax/PV',tf32=False,reduced_precision_reduction=False,query_positions='floor(i*(N-1)/31), i=0..31',query_chunk=8,all_causal_valid_keys=True,unit='document x head over 32 sampled query vectors',quantile='NumPy linear',primary_round=0),data=dict(dev_documents=8,dev_manifest_sha256=sha(CASE/'inputs/dev_manifest.json'),historical_role='16 Case004 observed confirmation docs, no fresh label or unnecessary rerun',fresh_documents=16,fresh_languages={'en':5,'ko':5,'code':6},fresh_rule='fresh_inputs.document index=100+i; IDs c005-fresh-00..15; fixed archive generator, deterministic no RNG; plain tokenizer without special tokens',fresh_uniqueness='ID, text SHA256, first512 exact-token hash disjoint from all Case004 DEV/HISTORICAL and within fresh',fresh_gpu_gate='Only if one DEV finalist qualifies; otherwise no generation/capture/evaluation'),timing=dict(dev_processes=2,dev_blocks=5,fresh_processes=5,fresh_blocks=20,warmup=20,calls_per_block=10,primary='Complete BF16 GPU-input to BF16 output, synchronized wall block mean including wrapper/preprocessing/allocation',secondary='Separate CUDA event block; not host overhead',order_seed='505100+round*10000+length+document_index*37; balanced rotations',cost_outside=['capture','CPU-GPU copies','reference','profiler','I/O','first-call/compile'],eager=True,cache='Warm repeated inputs; no quantized memoization',kernel_only=False),statistics=dict(bootstrap=5000,timing_seed=505901,numerical_seed=505902,timing='Crossed document and GLOBAL process resampling; cell paired-block resampling; same random indices across configs',numerical='Document clusters, all16 heads',interval='percentile 95%, linear; pointwise, not population guarantee',speedup='median of paired BF16/candidate block ratios; ratio of medians separate'),resources=dict(peak_allocated_max_bytes=13*2**30,minimum_free_bytes=4*2**30,build_attempts_max=2,builds_used=0,gpu_serial=True,weights_download=False),failure_policy='Stop invalid config at smoke; no source patch. Stop whole run on input/capture/fingerprint/environment failure; preserve raw failure. Missing/undefined prevents GO; no confirmation candidate swap.',prefix_stress='Same Case004 D128 seed400135 fixture; futureV x1000 and range-preserving permutation; B and anchor tested, finalist only if selected; separate from ordinary error screen',pareto='DEV observed point-estimate dominance in complete wall latency, median error and p95 error; no weighted score',capture_gate='Same-fingerprint native BF16 replay must be bitwise equal')
 else:
  pa,pa_sha=verify_phase('a');assert a.dev_summary
  result=json.loads(a.dev_summary.read_text());assert result['phase_sha256']==pa_sha and result['finalist_id'] in ['V1','V2','V3','V4']
  from scripts.analyze import analyze
  fresh_selection=analyze('dev');assert fresh_selection==result,'DEV summary differs from raw recomputation'
  assert not list((CASE/'results/fresh').glob('*.json')) and not (CASE/'provenance/fresh_capture.json').exists()
  m=json.loads((CASE/'inputs/fresh_manifest.json').read_text());assert len(m['documents'])==16
  s=dict(protocol_version=1,phase='B',frozen_at_utc=utc(),phase_a_sha256=pa_sha,environment_fingerprint=pa['environment_fingerprint'],model_revision=pa['model_revision'],finalist_id=result['finalist_id'],effective_settings=effective(result['finalist_id']),bf16_backend=pa['bf16_backend'],fresh_manifest_sha256=sha(CASE/'inputs/fresh_manifest.json'),dev_summary_sha256=sha(a.dev_summary),confirmation_policy='B, A_PUBLIC, one frozen finalist; 16 documents x3 lengths x5 processes, no substitution')
 files=[p for d in ['src','scripts','tests','inputs'] for p in (CASE/d).rglob('*') if p.is_file() and '__pycache__' not in p.parts]
 files += [p for p in (CASE/'provenance').glob('*.json')]
 s['frozen_files']={str(p.relative_to(CASE)):sha(p) for p in sorted(files)}
 write_json(target,s);(CASE/f'configs/phase_{a.phase}.sha256').write_text(sha(target)+'\n');print(json.dumps({'phase':a.phase,'sha256':sha(target),'files':len(files),'configs':s.get('executable_configs')}))
if __name__=='__main__':main()
